import { EMTPY_STATE_ASSET_MAP } from './assets/VisualPresetVariants.js';
import type { EmptyStateVisualPresetProps } from './slot-components/VisualPreset.js';
import { HeadingLevel, HeadingTag } from '../../core/types/heading.js';

/**  Based on the content subcontainer's min-width, spacing,
 * and visual container dimensions (320px + 64px + 320px)
 * @internal
 */
export const _MIN_CONTAINER_WIDTH = 704;

/**
 * @internal
 */
export function _getHeadingVariant(size: 'small' | 'default' | 'large'): {
  level: HeadingLevel;
  tag: HeadingTag;
} {
  if (size === 'small') {
    return { level: 6, tag: 'h6' };
  }

  if (size === 'large') {
    return { level: 1, tag: 'h1' };
  }

  return { level: 3, tag: 'h3' };
}

/**
 * @internal
 */
export function _generateVisualPresetCdnUrl(
  context: EmptyStateVisualPresetProps['context'],
  type: EmptyStateVisualPresetProps['type'],
  theme: 'light' | 'dark',
): string {
  return EMTPY_STATE_ASSET_MAP[context][type][theme];
}
